import math

def check_solution(n, target_N=2007):
    """Checks if a given n can produce N=2007 for some integer r (0 <= r <= n)."""

    # Check discriminant D = 24144 - 3n^2
    discriminant = 24144 - 3 * (n**2)

    if discriminant < 0:
        return False, None

    k = math.isqrt(discriminant)

    if k * k != discriminant:
        return False, None  # D must be a perfect square

    # Check if r is an integer: r = (3n +/- k) / 6

    for sign in [-1, 1]:
        numerator = 3 * n + sign * k
        if numerator % 6 == 0:
            r_candidate = numerator // 6

            # Check constraints: r must be an integer between 0 and n
            if 0 <= r_candidate <= n:
                b_candidate = n - r_candidate

                # Verify the count
                # N = (r^3 + b^3) / n
                try:
                    count = (r_candidate**3 + b_candidate**3) / n
                except ZeroDivisionError:
                    # Should not happen as we check n >= 1
                    continue

                if count == target_N:
                    return True, r_candidate

    return False, None

# Test n values up to 90 (max theoretical bound)
max_n = 90
solutions = []
for n in range(1, max_n + 1):
    found, r = check_solution(n)
    if found:
        solutions.append((n, r))

print(solutions)

