        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

N_MAX = 68
solutions = set()

print("Starting check for n = 1 to 68.")

for n in range(1, N_MAX + 1):
    # Calculate the discriminant D
    D = 24144 - 3 * (n**2)

    if is_perfect_square(D):
        k = int(math.isqrt(D))

        # Check r1: r = (3n + k) / 6
        numerator1 = 3 * n + k
        if numerator1 % 6 == 0:
            r1 = numerator1 // 6
            if 1 <= r1 <= n - 1:
                solutions.add((n, r1))

        # Check r2: r = (3n - k) / 6
        numerator2 = 3 * n - k
        if numerator2 % 6 == 0:
